 c=read(ROOT/'data/measurement_contract.json');m=gzread(ROOT/'full_measurement/violet_v02/full_measurements.json.gz');a=read(FULL/'data/volume_annotations_v03.json');ap=FULL/'data/accessory_annotations.json';p=read(ap);src=np.array(Image.open(REPO/c['source']).convert('RGB'));_,base=extract(ROOT/'data/measurement_contract.json');masks=dict(np.load(ROOT/'full_measurement/violet_v02/semantic_masks.npz'));masks.update({v+'_foreground':base[v+'_foreground'] for v in c['views']});a['parts']=[p['bouquet']];ops,mats,e,s=volume_parts(c,m,a,masks,src);ann=read(ROOT/'data/violet_surface_branch_annotations.json');fv=c['views']['front'];scale=c['alignment']['character_height_m_for_test']/fv['scale_px_per_unit'];im=Image.new('1',(src.shape[1],src.shape[0]));d=ImageDraw.Draw(im)
